// 1. Place E-Commerce Order (Saga Entrypoint)
POST /api/v1/orders
Headers:
  Idempotency-Key: checkout_usr881_cart42
Request:
{
  "customer_id": "usr_881",
  "shipping_address_id": "addr_102",
  "payment_method_id": "pm_visa_9912",
  "items": [
    { "sku_id": "SKU-PS5-PRO", "quantity": 1, "unit_price_cents": 69900 }
  ]
}
Response (201 Created):
{
  "order_id": "ord_01HV9Z1029",
  "saga_state": "CONFIRMED",
  "total_cents": 75492,
  "inventory_reservation_id": "res_88412",
  "payment_id": "pay_99102"
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY orders (Sharded PostgreSQL (by customer_id)) {
  [PK ] order_id               UUID
  [IDX] customer_id            UUID
  [IDX] idempotency_key        VARCHAR(128)
        total_cents            BIGINT
        saga_state             VARCHAR(32)
}

ENTITY order_items (Sharded PostgreSQL) {
  [PK ] order_item_id          UUID
  [FK ] order_id               UUID
  [IDX] sku_id                 VARCHAR(64)
        quantity               INT
        snapshot_price_cents   BIGINT
}

ENTITY inventory_reservations (Inventory DB + Redis Hot-SKU Cache) {
  [PK ] reservation_id         UUID
  [FK ] order_id               UUID
  [IDX] sku_id                 VARCHAR(64)
        reserved_qty           INT
        status                 ENUM('RESERVED','COMMITTED','RELEASED')
}

// Relationships: orders --(1 : N (line items))--> order_items --(1 : N (saga stock holds))--> inventory_reservations

/*
================================================================================
FLOW 1: SAGA ORCHESTRATOR HAPPY PATH vs. COMPENSATING ROLLBACK PATH
================================================================================
HAPPY PATH:
  [OrderSvc] --(ReserveInventoryCmd)--> [InventorySvc] (Available -= qty, Reserved += qty)
  [OrderSvc] <--(InventoryReservedEvt)-- [InventorySvc]
  [OrderSvc] --(ProcessPaymentCmd)----> [PaymentSvc]   (Charge Buyer Card)
  [OrderSvc] <--(PaymentCapturedEvt)--- [PaymentSvc]
  [OrderSvc] --(ConfirmInventoryCmd)--> [InventorySvc] (Reserved -= qty)
  [OrderSvc] --(FulfillOrderCmd)------> [FulfillmentSvc]

COMPENSATING ROLLBACK PATH (Payment Declined or 15-Min Timeout):
  [OrderSvc] <--(PaymentFailedEvt)----- [PaymentSvc]
  [OrderSvc] --(ReleaseInventoryCmd)--> [InventorySvc] (Reserved -= qty, Available += qty)
  [OrderSvc] <--(InventoryReleasedEvt)- [InventorySvc] -> Order Status = CANCELLED_PAYMENT_FAILED

================================================================================
FLOW 2: 64-WAY STRIPED INVENTORY RESERVATION (ELIMINATES HOT-ROW LOCK CONTENTION)
================================================================================
SKU "IPHONE_17" (Total Stock = 6,400) -> Split across 64 DB rows (100 units per bucket_id 0..63)
Buyer Order "ord_8812" -> bucket_id = hash("ord_8812") % 64 = Bucket #19
SQL: UPDATE sku_inventory_buckets
     SET available_qty = available_qty - :qty, reserved_qty = reserved_qty + :qty
     WHERE sku_id = 'IPHONE_17' AND bucket_id = 19 AND available_qty >= :qty;
*/

package com.sdi.ecommerce.service;

import com.sdi.ecommerce.domain.*;
import java.time.Duration;
import java.time.Instant;
import java.util.*;

public class OrderSagaAndInventoryEngine {

    private static final int NUM_INVENTORY_BUCKETS = 64;
    private static final Duration RESERVATION_TTL = Duration.ofMinutes(15);

    private final SagaRepository sagaRepo;
    private final InventoryRepository inventoryRepo;
    private final RedisInventoryGate redisGate;

    public OrderSagaAndInventoryEngine(
        SagaRepository sagaRepo,
        InventoryRepository inventoryRepo,
        RedisInventoryGate redisGate
    ) {
        this.sagaRepo = sagaRepo;
        this.inventoryRepo = inventoryRepo;
        this.redisGate = redisGate;
    }

    /**
     * FLOW 1: Saga Orchestrator handling Reply Events & Triggering Compensating Actions
     */
    public void onSagaReplyEvent(String orderId, String eventType, String eventPayload) {
        sagaRepo.executeInTransaction(tx -> {
            OrderEntity order = tx.lockOrderForUpdate(orderId);

            switch (eventType) {
                case "INVENTORY_RESERVED" -> {
                    tx.updateOrderStatus(orderId, OrderStatus.INVENTORY_RESERVED);
                    tx.updateSagaStep(orderId, SagaStep.PROCESS_PAYMENT);
                    tx.insertOutboxCommand("CMD_PROCESS_PAYMENT", orderId, order);
                }
                case "INVENTORY_OUT_OF_STOCK" -> {
                    tx.updateOrderStatus(orderId, OrderStatus.CANCELLED_OUT_OF_STOCK);
                    tx.updateSagaStep(orderId, SagaStep.ABORTED);
                }
                case "PAYMENT_CAPTURED" -> {
                    tx.updateOrderStatus(orderId, OrderStatus.PAYMENT_CAPTURED);
                    tx.updateSagaStep(orderId, SagaStep.SCHEDULE_FULFILLMENT);
                    tx.insertOutboxCommand("CMD_CONFIRM_INVENTORY", orderId, order);
                    tx.insertOutboxCommand("CMD_SCHEDULE_FULFILLMENT", orderId, order);
                }
                case "PAYMENT_FAILED", "PAYMENT_TIMED_OUT" -> {
                    // Trigger Compensating Transaction to release reserved stock!
                    tx.updateSagaStep(orderId, SagaStep.COMPENSATE_RELEASE_INVENTORY);
                    tx.insertOutboxCommand("CMD_RELEASE_INVENTORY", orderId, order);
                }
                case "INVENTORY_RELEASED_COMPENSATED" -> {
                    tx.updateOrderStatus(orderId, OrderStatus.CANCELLED_PAYMENT_FAILED);
                    tx.updateSagaStep(orderId, SagaStep.ABORTED);
                }
                default -> throw new IllegalArgumentException("Unknown saga event: " + eventType);
            }
            return null;
        });
    }

    /**
     * FLOW 2: High-Throughput Striped Inventory Reservation (Redis Gate + 64-Bucket DB)
     */
    public boolean reserveStripedInventory(String orderId, String skuId, int quantity) {
        // 1. Sub-millisecond Redis Lua Token Gatekeeper
        if (!redisGate.tryDecrementStockToken(skuId, orderId, quantity)) {
            return false; // Fast-fail when flash-sale SKU is sold out
        }

        // 2. Hash orderId to a deterministic starting bucket (0..63) to spread DB row locks
        int primaryBucket = Math.floorMod(orderId.hashCode(), NUM_INVENTORY_BUCKETS);

        try {
            return inventoryRepo.executeInTransaction(tx -> {
                // Idempotency check: has this orderId already reserved this SKU?
                if (tx.reservationExists(orderId, skuId)) {
                    return true;
                }

                // Probe primary bucket first; if empty near end of flash sale, probe adjacent buckets
                int chosenBucket = -1;
                for (int offset = 0; offset < NUM_INVENTORY_BUCKETS; offset++) {
                    int candidateBucket = (primaryBucket + offset) % NUM_INVENTORY_BUCKETS;
                    int rowsUpdated = tx.decrementBucketIfAvailable(skuId, candidateBucket, quantity);
                    if (rowsUpdated == 1) {
                        chosenBucket = candidateBucket;
                        break;
                    }
                }

                if (chosenBucket == -1) {
                    throw new OutOfStockException("No single bucket had sufficient stock");
                }

                // Record reservation with 15-minute expiration TTL for Saga compensation
                tx.insertReservation(
                    UUID.randomUUID(),
                    orderId,
                    skuId,
                    chosenBucket,
                    quantity,
                    Instant.now().plus(RESERVATION_TTL)
                );
                return true;
            });
        } catch (Exception ex) {
            // Restore Redis token counter if DB transaction rolled back
            redisGate.restoreStockToken(skuId, orderId, quantity);
            return false;
        }
    }
}
